const upsertCompletionProjection = `-- name: UpsertCompletionProjection :one
INSERT INTO user_game_completion_projections(
    user_id, game_id, ending_count, hundred_percent_basis, weight,
    completion_at, basis, algorithm_version, updated_at
)
VALUES(
    $1, $2, $3,
    $4, $5, $6,
    $7, $8, $9
)
ON CONFLICT (user_id, game_id) DO UPDATE SET
    ending_count = EXCLUDED.ending_count,
    hundred_percent_basis = EXCLUDED.hundred_percent_basis,
    weight = EXCLUDED.weight,
    completion_at = EXCLUDED.completion_at,
    basis = EXCLUDED.basis,
    algorithm_version = EXCLUDED.algorithm_version,
    updated_at = EXCLUDED.updated_at
RETURNING user_id, game_id, ending_count, hundred_percent_basis, weight, completion_at, basis, algorithm_version, updated_at
`

type UpsertCompletionProjectionParams struct {
	UserID              pgtype.UUID        `json:"user_id"`
	GameID              pgtype.UUID        `json:"game_id"`
	EndingCount         int32              `json:"ending_count"`
	HundredPercentBasis bool               `json:"hundred_percent_basis"`
	Weight              float64            `json:"weight"`
	CompletionAt        pgtype.Timestamptz `json:"completion_at"`
	Basis               string             `json:"basis"`
	AlgorithmVersion    string             `json:"algorithm_version"`
	UpdatedAt           pgtype.Timestamptz `json:"updated_at"`
}

func (q *Queries) UpsertCompletionProjection(ctx context.Context, arg UpsertCompletionProjectionParams) (UserGameCompletionProjection, error) {
	row := q.db.QueryRow(ctx, upsertCompletionProjection,
		arg.UserID,
		arg.GameID,
		arg.EndingCount,
		arg.HundredPercentBasis,
		arg.Weight,
		arg.CompletionAt,
		arg.Basis,
		arg.AlgorithmVersion,
		arg.UpdatedAt,
	)
	var i UserGameCompletionProjection
	err := row.Scan(
		&i.UserID,
		&i.GameID,
		&i.EndingCount,
		&i.HundredPercentBasis,
		&i.Weight,
		&i.CompletionAt,
		&i.Basis,
		&i.AlgorithmVersion,
		&i.UpdatedAt,
	)
	return i, err
}
